s("insights_monthMixItem", "{quadrant}: {count, plural, =1{1 check-in} other{{count} check-ins}}", "Recap legend row (glyph + name + count), also read by screen readers.", "{quadrant}: {count, plural, =1{1 చెక్-ఇన్} other{{count} చెక్-ఇన్‌లు}}", "{quadrant}: {count, plural, =1{1 check-in} other{{count} check-ins}}", {"quadrant": {"type": "String"}, "count": {"type": "int"}}, hi="{quadrant}: {count, plural, =1{1 चेक-इन} other{{count} चेक-इन}}", hl="{quadrant}: {count, plural, =1{1 check-in} other{{count} check-ins}}")
s("insights_monthSkySemantic", "A sky of {count, plural, =1{1 star} other{{count} stars}}, one for each check-in in {month}", "Screen-reader label of the recap's drawn sky.", "{month}లో ఒక్కో చెక్-ఇన్‌కి ఒక్కో నక్షత్రం, మొత్తం {count, plural, =1{1 నక్షత్రం} other{{count} నక్షత్రాలు}}", "{month} lo prati check-in ki oka star, mottham {count, plural, =1{1 star} other{{count} stars}}", {"count": {"type": "int"}, "month": {"type": "String"}}, hi="{count, plural, =1{1 तारे का आसमान} other{{count} तारों का आसमान}}, {month} के हर चेक-इन के लिए एक तारा", hl="{count, plural, =1{1 taare ka aasmaan} other{{count} taaron ka aasmaan}}, {month} ke har check-in ke liye ek taara")
s("insights_deeperTitle", "Deeper monthly review", "Section of the recap with patterns across the month and habit × mood (Aura Plus).", "లోతైన నెలవారీ సమీక్ష", "Deeper monthly review", hi="महीने की गहरी झलक", hl="Mahine ka deeper review")
s("insights_deeperLocked", "Patterns across the month, with habits alongside moods, come with Aura Plus.", "Locked note on Free (PRD 14-states: blurred deeper chart, basic sky stays free).", "నెల మొత్తంలోని ధోరణులు, మూడ్‌లతో పాటు అలవాట్లు Aura Plus‌తో వస్తాయి.", "Nela mottham patterns, moods tho paatu habits Aura Plus tho vastaayi.", hi="पूरे महीने के पैटर्न, मूड के साथ आदतें, Aura Plus में मिलते हैं।", hl="Poore mahine ke patterns, moods ke saath habits, Aura Plus mein milte hain.")
s("insights_deeperNone", "No clear patterns this month.", "Plus recap: nothing passed the thresholds for that month.", "ఈ నెల స్పష్టమైన ధోరణులు ఏవీ లేవు.", "Ee nela clear patterns emi levu.", hi="इस महीने कोई साफ़ पैटर्न नहीं।", hl="Is mahine koi clear pattern nahi.")

